  if ($path==='/api/uploads/image'&&$method==='POST') { $requireAuth();$requireGuild();if(empty($_FILES['image']['tmp_name']))fail('IMAGE_REQUIRED_OR_INVALID');$f=$_FILES['image'];if($f['size']>8*1024*1024)fail('UPLOAD_TOO_LARGE');$mime=mime_content_type($f['tmp_name']);$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp','image/gif'=>'gif'][$mime]??null;if(!$ext)fail('IMAGE_REQUIRED_OR_INVALID');if(!is_dir(__DIR__.'/uploads'))mkdir(__DIR__.'/uploads',0755,true);$name=time().'-'.bin2hex(random_bytes(8)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],__DIR__.'/uploads/'.$name))fail('UPLOAD_FAILED',500);logAction($pdo,'file.uploaded',$me,'image',$name,['size'=>$f['size'],'mime'=>$mime]);out(['success'=>true,'url'=>'/uploads/'.$name,'filename'=>$name,'size'=>$f['size']],201); }
  if ($path==='/api/public/media') out(['items'=>[]]);
